-- The tables of the project, for Oracle 12c or later.
-- Generated by ElastiCORE from the model, in the column types that database's Hibernate dialect would
-- choose. Run it with spring.sql.init.schema-locations on an empty database.

CREATE SEQUENCE ref_tag_seq START WITH 1 INCREMENT BY 50;

CREATE TABLE ps_category (
    category_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(30 CHAR) NOT NULL,
    description VARCHAR2(3000 CHAR) NOT NULL,
    PRIMARY KEY (category_id)
);

CREATE TABLE ps_country (
    iso_code VARCHAR2(2 CHAR) NOT NULL,
    name VARCHAR2(80 CHAR) NOT NULL,
    printable_name VARCHAR2(80 CHAR) NOT NULL,
    PRIMARY KEY (iso_code)
);

CREATE TABLE ps_customer (
    customer_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    login VARCHAR2(10 CHAR) NOT NULL,
    password VARCHAR2(255 CHAR) NOT NULL,
    first_name VARCHAR2(50 CHAR) NOT NULL,
    last_name VARCHAR2(50 CHAR) NOT NULL,
    telephone VARCHAR2(30 CHAR),
    email VARCHAR2(100 CHAR),
    date_of_birth DATE,
    role VARCHAR2(1 CHAR),
    street1 VARCHAR2(50 CHAR),
    street2 VARCHAR2(50 CHAR),
    city VARCHAR2(50 CHAR),
    state VARCHAR2(50 CHAR),
    zipcode VARCHAR2(10 CHAR),
    country_code VARCHAR2(2 CHAR),
    PRIMARY KEY (customer_id)
);

CREATE TABLE ps_item (
    item_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(30 CHAR) NOT NULL,
    description VARCHAR2(3000 CHAR) NOT NULL,
    image_path VARCHAR2(100 CHAR),
    unit_cost NUMBER(10,2) NOT NULL,
    product_id NUMBER(19),
    PRIMARY KEY (item_id)
);

CREATE TABLE ps_order_line (
    line_id VARCHAR2(36 CHAR) NOT NULL,
    order_order_id VARCHAR2(36 CHAR),
    item_id NUMBER(19),
    quantity NUMBER(10) NOT NULL,
    unit_cost NUMBER(10,2),
    sub_total NUMBER(12,2),
    PRIMARY KEY (line_id)
);

CREATE TABLE ps_product (
    product_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(30 CHAR) NOT NULL,
    description VARCHAR2(3000 CHAR) NOT NULL,
    category_id NUMBER(19),
    discontinued_at TIMESTAMP(6) WITH TIME ZONE,
    PRIMARY KEY (product_id)
);

CREATE TABLE ps_purchase_order (
    order_id VARCHAR2(36 CHAR) NOT NULL,
    customer_id NUMBER(19),
    order_date DATE,
    status VARCHAR2(3 CHAR),
    street1 VARCHAR2(50 CHAR),
    street2 VARCHAR2(50 CHAR),
    city VARCHAR2(50 CHAR),
    state VARCHAR2(50 CHAR),
    zipcode VARCHAR2(10 CHAR),
    country_code VARCHAR2(2 CHAR),
    credit_card_number VARCHAR2(30 CHAR) NOT NULL,
    credit_card_type VARCHAR2(4 CHAR) NOT NULL,
    credit_card_exp_date VARCHAR2(5 CHAR) NOT NULL,
    total_without_vat NUMBER(12,2),
    vat_rate NUMBER(5,2),
    vat NUMBER(12,2),
    discount_rate NUMBER(5,2),
    discount NUMBER(12,2),
    total NUMBER(12,2),
    version NUMBER(19),
    PRIMARY KEY (order_id)
);

CREATE TABLE ref_case_note (
    note_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    title VARCHAR2(50 CHAR),
    status_code VARCHAR2(10 CHAR),
    PRIMARY KEY (note_id)
);

CREATE TABLE ref_color_tag (
    retired_at TIMESTAMP(6) WITH TIME ZONE,
    tag_id NUMBER(19) NOT NULL,
    label VARCHAR2(30 CHAR) NOT NULL,
    note_note_id NUMBER(19),
    rgb VARCHAR2(6 CHAR),
    PRIMARY KEY (tag_id)
);

CREATE TABLE ref_company (
    registry_no VARCHAR2(20 CHAR),
    party_id NUMBER(19) NOT NULL,
    PRIMARY KEY (party_id)
);

CREATE TABLE ref_party (
    party_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    version NUMBER(19),
    left_at TIMESTAMP(6) WITH TIME ZONE,
    note_note_id NUMBER(19),
    PRIMARY KEY (party_id)
);

CREATE TABLE ref_person (
    birth_year NUMBER(10),
    party_id NUMBER(19) NOT NULL,
    PRIMARY KEY (party_id)
);

CREATE TABLE ref_region_code (
    code VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    country VARCHAR2(2 CHAR),
    PRIMARY KEY (code)
);

CREATE TABLE ref_size_tag (
    retired_at TIMESTAMP(6) WITH TIME ZONE,
    tag_id NUMBER(19) NOT NULL,
    label VARCHAR2(30 CHAR) NOT NULL,
    note_note_id NUMBER(19),
    measure VARCHAR2(5 CHAR),
    PRIMARY KEY (tag_id)
);

CREATE TABLE ref_status_code (
    code VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    phase VARCHAR2(10 CHAR),
    PRIMARY KEY (code)
);

ALTER TABLE ps_item ADD CONSTRAINT fk_ps_item_product FOREIGN KEY (product_id) REFERENCES ps_product (product_id);
ALTER TABLE ps_order_line ADD CONSTRAINT fk_ps_order_line_order FOREIGN KEY (order_order_id) REFERENCES ps_purchase_order (order_id);
ALTER TABLE ps_order_line ADD CONSTRAINT fk_ps_order_line_item FOREIGN KEY (item_id) REFERENCES ps_item (item_id);
ALTER TABLE ps_product ADD CONSTRAINT fk_ps_product_category FOREIGN KEY (category_id) REFERENCES ps_category (category_id);
ALTER TABLE ps_purchase_order ADD CONSTRAINT fk_ps_purchase_order_customer FOREIGN KEY (customer_id) REFERENCES ps_customer (customer_id);
ALTER TABLE ref_color_tag ADD CONSTRAINT fk_ref_color_tag_note FOREIGN KEY (note_note_id) REFERENCES ref_case_note (note_id);
ALTER TABLE ref_company ADD CONSTRAINT fk_ref_company_parent FOREIGN KEY (party_id) REFERENCES ref_party (party_id);
ALTER TABLE ref_party ADD CONSTRAINT fk_ref_party_note FOREIGN KEY (note_note_id) REFERENCES ref_case_note (note_id);
ALTER TABLE ref_person ADD CONSTRAINT fk_ref_person_parent FOREIGN KEY (party_id) REFERENCES ref_party (party_id);
ALTER TABLE ref_size_tag ADD CONSTRAINT fk_ref_size_tag_note FOREIGN KEY (note_note_id) REFERENCES ref_case_note (note_id);

CREATE UNIQUE INDEX uk_ps_customer_login ON ps_customer (login);
